// Package hazard implements Layer 1: a static scanner that reads an app's schema
// and SQL and reports known PostgreSQL -> Spanner (PostgreSQL interface) hazards.
// Every rule cites its source: official documentation or a reproducible probe
// (results/probe/probe.md, generated by `sc-exp probe`).
package hazard

import "github.com/shadowcut/shadowcut/internal/classify"

// Severity ranks findings.
type Severity string

const (
	Info   Severity = "info"
	Low    Severity = "low"
	Medium Severity = "medium"
	High   Severity = "high"
)

// Rank orders severities.
func (s Severity) Rank() int {
	switch s {
	case High:
		return 3
	case Medium:
		return 2
	case Low:
		return 1
	}
	return 0
}

// Doc links used as sources.
const (
	DocOverview    = "https://docs.cloud.google.com/spanner/docs/reference/postgresql/overview"
	DocKnownIssues = "https://docs.cloud.google.com/spanner/docs/reference/postgresql/known-issues-postgresql-interface"
	DocDataTypes   = "https://docs.cloud.google.com/spanner/docs/reference/postgresql/data-types"
	DocFunctions   = "https://docs.cloud.google.com/spanner/docs/reference/postgresql/functions-and-operators"
	DocQuerySyntax = "https://docs.cloud.google.com/spanner/docs/reference/postgresql/query-syntax"
	DocSchemaDes   = "https://docs.cloud.google.com/spanner/docs/schema-design"
	DocPKDefault   = "https://docs.cloud.google.com/spanner/docs/primary-key-default-value"
	DocIsolation   = "https://docs.cloud.google.com/spanner/docs/isolation-levels"
	DocCollation   = "https://docs.cloud.google.com/spanner/docs/reference/standard-sql/collation-concepts"
	DocPGOrder     = "https://www.postgresql.org/docs/16/queries-order.html"
	DocPGIsolation = "https://www.postgresql.org/docs/16/transaction-iso.html"
	Probe          = "experiment: results/probe/probe.md"
)

// Rule is a catalog entry.
type Rule struct {
	ID       string            `json:"id"`
	Title    string            `json:"title"`
	Severity Severity          `json:"severity"`
	Area     string            `json:"area"`               // hotspot | collation | ordering | null | timezone | precision | isolation | unsupported | semantics | naming
	Predicts classify.Category `json:"predicts,omitempty"` // mismatch class Layer 2 should observe; "" = not observable by shadow reads
	Explain  string            `json:"explain"`
	Fix      string            `json:"fix"`
	Sources  []string          `json:"sources"`
}

// Catalog lists every rule. Keep docs/HAZARDS.md in sync (TestCatalogDocumented).
var Catalog = []Rule{
	// ---- schema: hotspots -------------------------------------------------
	{ID: "SC-SEQ-KEY", Title: "Sequential primary key (serial / identity / nextval)", Severity: High, Area: "hotspot",
		Explain: "Monotonically increasing keys send every insert to the same key range (one split), creating a write hotspot that limits throughput.",
		Fix:     "Use a UUIDv4 key, or a bit-reversed sequence (CREATE SEQUENCE ... bit_reversed_positive), or prefix the key with a hash shard.",
		Sources: []string{DocSchemaDes, DocPKDefault}},
	{ID: "SC-MONO-TS-KEY", Title: "Primary key starts with a timestamp", Severity: High, Area: "hotspot",
		Explain: "A timestamp as the first key part is monotonically increasing and concentrates writes on one split.",
		Fix:     "Put a high-cardinality, well-distributed column first, or add a hash shard column.",
		Sources: []string{DocSchemaDes}},
	{ID: "SC-MONO-INDEX", Title: "Non-interleaved index on a monotonically increasing column", Severity: Medium, Area: "hotspot",
		Explain: "Spanner implements indexes as tables; an index whose first column is a timestamp or sequence has the same hotspot problem as the base table.",
		Fix:     "Lead the index with a well-distributed column, add a shard column, or interleave it under a parent.",
		Sources: []string{DocSchemaDes}},
	// ---- schema: types ------------------------------------------------------
	{ID: "SC-NUMERIC-TYPMOD", Title: "numeric(p,s) loses its precision/scale on Spanner", Severity: Medium, Area: "precision", Predicts: classify.Precision,
		Explain: "Type modifiers are rejected in Spanner DDL (\"Type modifier is not supported for type <numeric>\"). Postgres rounds every write to the declared scale; after cutover Spanner stores unrounded values (probe: 3.33333 stays 3.3333300000000000).",
		Fix:     "Round explicitly in the application (or in DML) before writing, and compare with a tolerance where scale matters.",
		Sources: []string{DocDataTypes, Probe}},
	{ID: "SC-KEY-TYPE", Title: "numeric / jsonb / real column used in a key or index", Severity: High, Area: "unsupported",
		Explain: "Spanner does not allow NUMERIC, FLOAT4 or JSONB as primary key, foreign key or secondary index columns.",
		Fix:     "Key on bigint/text/uuid; keep numeric/jsonb as non-key columns.",
		Sources: []string{DocDataTypes}},
	{ID: "SC-UNSUP-TYPE", Title: "Column type not supported by Spanner", Severity: High, Area: "unsupported", Predicts: classify.Unsupported,
		Explain: "Spanner's PostgreSQL interface supports a fixed set of types; timestamp without time zone, char(n), money, inet, interval columns, json, xml, tsvector, enums and others are not supported.",
		Fix:     "Map to a supported type (timestamptz, varchar, numeric, text, jsonb) and adjust the code that relies on the original semantics.",
		Sources: []string{DocDataTypes, Probe}},
	{ID: "SC-INT4", Title: "integer/smallint become 8-byte bigint", Severity: Low, Area: "semantics",
		Explain: "Spanner maps int/integer to int8. Overflow errors that Postgres raises at 2^31 no longer happen, and int4 casts fail (probe: \"cannot cast type bigint to integer\").",
		Fix:     "Declare bigint explicitly and remove reliance on int4 overflow checks or ::int4 casts.",
		Sources: []string{DocDataTypes, Probe}},
	{ID: "SC-UNSUP-DDL", Title: "Unsupported schema feature (trigger, function, extension, partial index, custom type, ...)", Severity: High, Area: "unsupported",
		Explain: "Spanner does not support triggers, SERIAL without default_sequence_kind, savepoints, transactional DDL, partial indexes, extensions, foreign data wrappers, or user-defined types/functions/operators.",
		Fix:     "Move the logic into the application or a change stream consumer; replace partial indexes with full indexes (or NULL_FILTERED indexes).",
		Sources: []string{DocOverview}},
	{ID: "SC-IDENT-UNDERSCORE", Title: "Identifier starts with an underscore", Severity: Medium, Area: "naming",
		Explain: "Spanner identifiers must start with a letter (\"Table name not valid: _sc_offsets.\", docs/BUGS.md BUG-002).",
		Fix:     "Rename the object.",
		Sources: []string{"experiment: docs/BUGS.md BUG-002"}},
	// ---- query: ordering / collation ---------------------------------------
	{ID: "Q-COLLATION-ORDER", Title: "ORDER BY on text uses a different collation", Severity: High, Area: "collation", Predicts: classify.Collation,
		Explain: "PostgreSQL sorts text with the database collation (en_US.UTF-8 here: case- and accent-aware, punctuation ignored at first level). Spanner sorts by Unicode code point (probe: 'Banana, Zebra, _under, apple, straße, éclair' vs 'apple, Banana, éclair, straße, _under, Zebra'). Page boundaries (LIMIT/keyset) select different rows.",
		Fix:     "Sort on a normalized key computed identically on both sides (e.g. a stored sort_key column), or accept code-point order and update tests; COLLATE is not supported on Spanner.",
		Sources: []string{Probe, DocCollation}},
	{ID: "Q-COLLATION-COMPARE", Title: "Range comparison / min / max / greatest on text", Severity: Medium, Area: "collation", Predicts: classify.Collation,
		Explain: "<, >, BETWEEN, min(), max(), greatest() and least() on text follow the collation, so filters and aggregates return different rows/values (probe: s > 'a' matches 7 rows on Postgres, 4 on Spanner).",
		Fix:     "Compare on a normalized key, or restrict to ASCII-only, case-normalized data where both orders agree.",
		Sources: []string{Probe}},
	{ID: "Q-ORDER-TIES", Title: "ORDER BY does not determine a unique order", Severity: Medium, Area: "ordering", Predicts: classify.Nondeterminism,
		Explain: "When ORDER BY keys tie, the order among tied rows is unspecified; the two engines break ties differently, and with LIMIT they return different rows.",
		Fix:     "Append a unique column (the primary key) as a final tiebreaker.",
		Sources: []string{DocPGOrder}},
	{ID: "Q-LIMIT-NO-ORDER", Title: "LIMIT/OFFSET without ORDER BY", Severity: High, Area: "ordering", Predicts: classify.Nondeterminism,
		Explain: "Without ORDER BY, LIMIT returns an arbitrary subset; Spanner's choice differs from Postgres's.",
		Fix:     "Add an ORDER BY over a unique key.",
		Sources: []string{DocPGOrder}},
	{ID: "Q-NULL-ORDER", Title: "ORDER BY on a nullable column without NULLS FIRST/LAST", Severity: Low, Area: "null", Predicts: classify.NullOrdering,
		Explain: "Default NULL placement is an engine choice. On the emulator the PostgreSQL interface matches Postgres (NULLS LAST ascending, FIRST descending; probe order_nulls_default_*), unlike Spanner's GoogleSQL dialect. Kept as a low-severity reminder until confirmed on real Spanner.",
		Fix:     "State NULLS FIRST / NULLS LAST explicitly.",
		Sources: []string{Probe, DocQuerySyntax}},
	// ---- query: NULL / function semantics ----------------------------------
	{ID: "Q-CONCAT-NULL", Title: "concat()/array_cat()/array_to_string() return NULL if any argument is NULL", Severity: High, Area: "null", Predicts: classify.NullSemantics,
		Explain: "PostgreSQL's concat() ignores NULL arguments; Spanner's returns NULL (documented known issue; probe fn_concat: 'apple' vs NULL).",
		Fix:     "Wrap nullable arguments in coalesce(x, '').",
		Sources: []string{DocKnownIssues, Probe}},
	{ID: "Q-FUNC-SEMANTICS", Title: "Function returns different results on Spanner", Severity: Medium, Area: "semantics", Predicts: classify.FuncSemantics,
		Explain: "Observed differences: upper('straße') = 'STRASSE' (full Unicode case mapping) vs 'STRAßE'; lower('İ') differs; round(2.5::float8) = 3 vs 2 (half-even in Postgres); quote_ident quotes everything; power() underflow returns 0 instead of an error.",
		Fix:     "Avoid relying on these functions for identifiers/keys; compute in the application where exact behaviour matters.",
		Sources: []string{Probe, DocKnownIssues}},
	// ---- query: time zones ---------------------------------------------------
	{ID: "Q-TZ-DEFAULT", Title: "Date/time function depends on the default time zone", Severity: High, Area: "timezone", Predicts: classify.Timezone,
		Explain: "Spanner evaluates 2-argument date_trunc, extract, to_char, ::date, ::text and timestamptz + interval in America/Los_Angeles (even though SHOW timezone reports UTC); Postgres uses the session time zone (UTC here). Day buckets shift by 7-8 hours and DST changes interval arithmetic (probe fn_date_trunc, fn_extract, fn_to_char, fn_cast_ts_*, fn_interval_add).",
		Fix:     "Pass the time zone explicitly: date_trunc('day', ts, 'UTC'); do calendar math in the application.",
		Sources: []string{DocFunctions, Probe}},
	// ---- query: precision ---------------------------------------------------
	{ID: "Q-FLOAT-AGG", Title: "sum/avg over floating-point columns", Severity: Medium, Area: "precision", Predicts: classify.Precision,
		Explain: "Floating-point addition is not associative; distributed aggregation adds in a different order, changing the last digits (observed: 1.0274024412846794 vs 1.0274024412846792).",
		Fix:     "Use numeric for values that are compared exactly, or round results before comparing/displaying.",
		Sources: []string{"experiment: results/exp1 (float_avg_by_wiki)"}},
	// ---- query: unsupported -------------------------------------------------
	{ID: "Q-UNSUP-FUNC", Title: "Function not supported by Spanner", Severity: High, Area: "unsupported", Predicts: classify.Unsupported,
		Explain: "The function (for the argument types used) is rejected by Spanner's PostgreSQL interface; the statement fails at runtime.",
		Fix:     "Rewrite with a supported equivalent or compute in the application.",
		Sources: []string{Probe, DocFunctions}},
	{ID: "Q-UNSUP-SYNTAX", Title: "Query syntax not supported by Spanner", Severity: High, Area: "unsupported", Predicts: classify.Unsupported,
		Explain: "Rejected constructs observed: DISTINCT ON, row-value comparisons, COLLATE, = ANY('{..}') array literals, WITH RECURSIVE, window functions (OVER), LATERAL, GROUPING SETS/ROLLUP, SIMILAR TO, FOR UPDATE outside a read-write transaction, SKIP LOCKED/NOWAIT, set-returning functions in the select list, timestamp without time zone.",
		Fix:     "Rewrite (e.g. keyset pagination as (a < $1) OR (a = $1 AND b < $2); ANY(ARRAY[...]) instead of '{...}').",
		Sources: []string{Probe, DocQuerySyntax, DocFunctions}},
	{ID: "Q-ILIKE", Title: "ILIKE operator", Severity: Info, Area: "unsupported",
		Explain: "The documentation lists case-insensitive matching via pg.ilike(); the emulator accepts the ILIKE operator (probe syn_ilike). Confirm on real Spanner.",
		Fix:     "If rejected on real Spanner, use lower(col) LIKE lower($1) or pg.ilike(col, $1).",
		Sources: []string{DocFunctions, Probe}},
	// ---- isolation -------------------------------------------------------------
	{ID: "Q-ISOLATION-LEVEL", Title: "Isolation level not available on Spanner", Severity: High, Area: "isolation",
		Explain: "Spanner supports SERIALIZABLE (default) and REPEATABLE READ only; READ COMMITTED / READ UNCOMMITTED requests are not honoured.",
		Fix:     "Use the default serializable isolation (or repeatable read) and add abort-retry loops.",
		Sources: []string{DocIsolation}},
	{ID: "Q-ISOLATION-RMW", Title: "Read-modify-write transaction relies on READ COMMITTED behaviour", Severity: Medium, Area: "isolation", Predicts: classify.Isolation,
		Explain: "A transaction reads a row without FOR UPDATE and then writes it. Under Postgres's default READ COMMITTED, concurrent runs silently lose updates; Spanner (serializable) aborts one transaction instead, which surfaces as errors unless the app retries.",
		Fix:     "Use a single atomic UPDATE (SET n = n + 1), or SELECT ... FOR UPDATE, and wrap transactions in a retry loop for aborts (SQLSTATE 40001).",
		Sources: []string{DocIsolation, DocPGIsolation, "experiment: results/isolation"}},
	{ID: "Q-UNSUP-TXN", Title: "Unsupported transaction feature (SAVEPOINT, LISTEN/NOTIFY, temp tables)", Severity: High, Area: "unsupported",
		Explain: "Spanner does not support savepoints, LISTEN/NOTIFY, or temporary tables.",
		Fix:     "Restructure transactions; use Pub/Sub or change streams for notifications.",
		Sources: []string{DocOverview}},
}

// RuleByID indexes the catalog.
var RuleByID = func() map[string]Rule {
	m := map[string]Rule{}
	for _, r := range Catalog {
		m[r.ID] = r
	}
	return m
}()
